/*
b = argmin_(i ∈ ℝ) i^2 
        where 
        a: scalar 
*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>
#include <LBFGS.h>
#include <LBFGSB.h>
#include <limits>
#include <stdexcept>
#include "type_helper.h"

using namespace iheartmesh;
struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    DT b;

    heartlib(const double & a)
    {

        // b = argmin_(i ∈ ℝ) i^2
            auto unpack = [&](const VectorD & X, DT & i)
            {
                i = X(0);
            };
            auto target = [&](const VectorD & X)
            {
                DT i;
                unpack(X, i);
                return DT(pow(i, 2));
            };
            VectorD best_X;
            DT best_f = std::numeric_limits<DT>::infinity();
            auto helper = [&](const VectorD & X, VectorD & grad)
            {
                VectorD Xh = X;
                for(int k = 0; k < X.size(); ++k)
                {
                    const DT h = 1e-6 * std::max(DT(1), std::abs(X(k)));
                    Xh(k) = X(k) + h;
                    const DT f_plus = target(Xh);
                    Xh(k) = X(k) - h;
                    const DT f_minus = target(Xh);
                    Xh(k) = X(k);
                    grad(k) = (f_plus - f_minus) / (2 * h);
                }
                const DT f = target(X);
                if(f < best_f){ best_f = f; best_X = X; }  // the best point evaluated, kept if the line search gives up
                return f;
            };
            VectorD lower = VectorD::Constant(1, -std::numeric_limits<DT>::infinity());
            VectorD upper = VectorD::Constant(1, std::numeric_limits<DT>::infinity());
            VectorD init = VectorD::Zero(1);
            init = init.cwiseMax(lower).cwiseMin(upper);
            DT fx;
            LBFGSpp::LBFGSParam<DT> param;
            param.epsilon = 1e-8;
            param.max_iterations = 1000;
            LBFGSpp::LBFGSSolver<DT> solver(param);
            try
            {
                solver.minimize(helper, init, fx);
            }
            catch(const std::runtime_error &)
            {
                // LBFGSpp's line search could not decrease the objective further (e.g. near a
                // nonsmooth or exactly zero minimum): use the best point evaluated
                if(!(best_f < std::numeric_limits<DT>::infinity())) throw;
            }
            init = best_X;
            fx = best_f;
            DT i;
            unpack(init, i);
        b = i;
    }
};

outputs.matlab:
function output = heartlib(a)
% output = heartlib(a)
%
%    b = argmin_(i ∈ ℝ) i^2 
%            where 
%            a: scalar 
    assert(numel(a) == 1);

    i = optimvar('i');
    target = @(i) i.^2;
    [optimize, ~] = fminunc(target,0);
    b = optimize;
    output.b = b;
end

